"""Canonical vendor-neutral enterprise taxonomy."""
from copy import deepcopy
DOMAINS=tuple({"domain_id":x[0],"name":x[1],"description":x[2]} for x in [["msme","MSME","Micro, small and medium enterprise ecosystem."],["sme","SME","Small and medium-sized enterprise ecosystem."],["startups","Startups","Early-stage ventures and startup ecosystem."],["solo_preneur","Solo-preneur","Independent owner-operated entrepreneur."],["solo_preneurship","Solo-preneurship","Solo business models and independent work."],["business_men","Business Men","Men participating in business ownership and leadership."],["business_women","Business Women","Women participating in business ownership and leadership."],["women_preneur","Women-preneur","Women founders and independent business operators."],["women_preneurship","Women-preneurship","Women-led venture creation and growth."],["men_preneur","Men-preneur","Men founders and independent business operators."],["men_preneurship","Men-preneurship","Men-led venture creation and growth."],["entrepreneurs","Entrepreneurs","Founders, owners, operators and business builders."],["entrepreneurship","Entrepreneurship","Opportunity discovery, venture creation and value creation."],["entrepreneurial_research","Entrepreneurial Research","Market, customer, sector and feasibility research."],["business_research","Business Research","Applied enterprise research and decision support."],["innovation","Innovation","Product, service, process and business-model innovation."],["business_creation","Business Creation","Idea development, formation readiness and launch."],["business_development","Business Development","Partnerships, markets, revenue and capability building."],["business_growth","Business Growth","Customer, revenue, team and sustainable growth."],["business_management","Business Management","Strategy, governance, finance and operations."],["business_model_design","Business Model Design","Value propositions and revenue architecture."],["startup_validation","Startup Validation","Customer discovery and product-market evidence."],["incubation_acceleration","Incubation and Acceleration","Incubators, accelerators and venture studios."],["funding_investment_readiness","Funding and Investment Readiness","Bootstrapping, grants, debt and investor readiness."],["digital_entrepreneurship","Digital Entrepreneurship","Digital-first and online business ventures."],["ai_technology_entrepreneurship","AI and Technology Entrepreneurship","AI, software and deep-tech ventures."],["research_development_rd","Research and Development","Applied R&D, prototyping and commercialization."],["intellectual_property_commercialization","IP Commercialization","IP strategy, licensing and technology transfer."],["social_rural_entrepreneurship","Social and Rural Entrepreneurship","Inclusive, rural and impact-led ventures."],["family_business_succession","Family Business and Succession","Family enterprise governance and transition."],["international_entrepreneurship","International Entrepreneurship","Cross-border venture development and exports."]])
def list_domains(): return deepcopy(list(DOMAINS))
def get_domain(key):
 k=key.strip().casefold(); return next((deepcopy(x) for x in DOMAINS if x["domain_id"]==k),None)
def search_domains(q):
 k=q.strip().casefold(); return [deepcopy(x) for x in DOMAINS if k and k in " ".join(x.values()).casefold()]
def validate_domains():
 ids=[x["domain_id"] for x in DOMAINS]; return {"valid":len(ids)==len(set(ids)),"count":len(ids)}
